import { useEffect, useState } from 'react';
import { useSelector } from 'react-redux';
import {
  Navigate,
  Outlet,
  useLocation,
  useNavigate,
  useParams
} from 'react-router-dom';
import Footer from '~/components/Footer';
import Header from '~/components/Header';
import Loading from '~/components/Loading';
import { NotificationProvider } from '~/components/NotificationProvider';
import ErrorNotification from '~/components/notifications/ErrorNotification';
import SuccessNotification from '~/components/notifications/SuccessNotification';
import Sidebar from '~/components/Sidebar';
import { useSession } from '~/data/hooks/session';
import { useAppDispatch } from '~/data/hooks/store';
import { LoadingStatus } from '~/types/Meta';
import { addNamespaceToPath } from '~/utils/helpers';
import type { RootState } from '~/store';
import { fetchInfoAsync, selectConfig } from './meta/metaSlice';
import {
  currentNamespaceChanged,
  useListNamespacesQuery
} from './namespaces/namespacesSlice';
import CommandDialog from '~/components/command/CommandDialog';
import Banner from '~/components/Banner';
import { selectDismissedBanner } from './events/eventSlice';

function InnerLayout() {
  const { session } = useSession();
  const [sidebarOpen, setSidebarOpen] = useState(false);

  const dismissedBanner = useSelector(selectDismissedBanner);
  const dispatch = useAppDispatch();

  const { namespaceKey } = useParams();
  const location = useLocation();
  const navigate = useNavigate();
  const savedNamespaceKey = useSelector(
    (state: RootState) => state.namespaces.currentNamespace
  );
  const config = useSelector(selectConfig);

  const namespaces = useListNamespacesQuery();

  useEffect(() => {
    const visible = namespaces.data?.namespaces;
    if (!visible?.length) {
      return;
    }

    const selected =
      visible.find((ns) => ns.key === namespaceKey) ||
      visible.find((ns) => ns.key === savedNamespaceKey) ||
      visible[0];

    if (savedNamespaceKey !== selected.key) {
      dispatch(currentNamespaceChanged(selected));
    }

    if (namespaceKey && namespaceKey !== selected.key) {
      navigate(addNamespaceToPath(location.pathname, selected.key), { replace: true });
    } else if (
      !namespaceKey &&
      /^\/(flags|segments|console)(\/|$)/.test(location.pathname)
    ) {
      navigate(addNamespaceToPath(location.pathname, selected.key), { replace: true });
    }
  }, [
    namespaces.data,
    namespaceKey,
    savedNamespaceKey,
    dispatch,
    navigate,
    location.pathname
  ]);

  useEffect(() => {
    dispatch(fetchInfoAsync());
  }, [dispatch]);

  if (!session) {
    return <Navigate to="/login" />;
  }

  if (namespaces.isLoading || config.status != LoadingStatus.SUCCEEDED) {
    return <Loading fullScreen />;
  }

  return (
    <>
      <Sidebar setSidebarOpen={setSidebarOpen} sidebarOpen={sidebarOpen} />
      <div className="flex min-h-screen flex-col bg-background md:pl-64">
        <Header setSidebarOpen={setSidebarOpen} />
        {!dismissedBanner && (
          <Banner
            title="Introducing Flipt Cloud"
            description="Fully managed Flipt. Multiple Environments. Integrated with your Git Repositories."
			ctx := authmiddlewaregrpc.ContextWithAuthentication(context.Background(), adminAuth)
			_, err := AuthorizationRequiredInterceptor(zap.NewNop(), verifier)(ctx, &flipt.ListNamespaceRequest{}, &grpc.UnaryServerInfo{}, func(ctx context.Context, _ any) (any, error) {
				called = true
				got, ok := authz.NamespacesFromContext(ctx)
				require.True(t, ok)
				assert.Equal(t, tt.namespaces, got)
				return nil, nil
			})
			assert.Equal(t, tt.wantHandler, called)
			assert.Equal(t, map[string]any{
				"authentication": adminAuth,
				"request":        flipt.NewRequest(flipt.ResourceNamespace, flipt.ActionRead, flipt.WithNoNamespace()),
			}, verifier.namespacesInput)
			assert.Nil(t, verifier.input)
			if tt.wantHandler {
				require.NoError(t, err)
			} else {
				require.Error(t, err)
			}
		})
	}
}

