func TestEngine_Namespaces(t *testing.T) {
	ctx := context.Background()
	policy, err := os.ReadFile("../testdata/namespaces.rego")
	require.NoError(t, err)
	server := sdktest.MustNewServer(sdktest.MockBundle("/bundles/bundle.tar.gz", map[string]string{
		"main.rego": string(policy),
	}))
	t.Cleanup(server.Stop)
	config := fmt.Sprintf(`{"services":{"test":{"url":%q}},"bundles":{"test":{"resource":"/bundles/bundle.tar.gz"}}}`, server.URL())
	opa, err := sdk.New(ctx, sdk.Options{
		Config: strings.NewReader(config),
		Store:  inmem.New(),
		Logger: ozap.Wrap(zaptest.NewLogger(t), &zap.AtomicLevel{}),
	})
	require.NoError(t, err)
	engine := &Engine{opa: opa, logger: zaptest.NewLogger(t)}
	t.Cleanup(func() { require.NoError(t, engine.Shutdown(ctx)) })

	for _, tt := range []struct {
		name  string
		roles []string
		want  []string
	}{
		{name: "no roles", want: []string{}},
		{name: "devs", roles: []string{"devs"}, want: []string{"local", "staging"}},
		{name: "ops", roles: []string{"ops"}, want: []string{"production"}},
		{name: "both", roles: []string{"devs", "ops"}, want: []string{"local", "staging", "production"}},
	} {
		t.Run(tt.name, func(t *testing.T) {
			got, err := engine.Namespaces(ctx, map[string]any{"authentication": map[string]any{"roles": tt.roles}})
			require.NoError(t, err)
			require.Equal(t, tt.want, got)
		})
	}
	got, err := engine.Namespaces(ctx, map[string]any{})
	require.NoError(t, err)
	require.Empty(t, got)
}

